class Solution:
    def compressedString(self, word: str) -> str:
        comp = []
        n = len(word)
        i = 0
        while i < n:
            c = word[i]
            j = i
            while j < n and word[j] == c:
                j += 1
            run = j - i
            while run > 0:
                k = min(9, run)
                comp.append(str(k))
                comp.append(c)
                run -= k
            i = j
        return "".join(comp)
