import json
from hypothesis import strategies as st

@st.composite
def gen(draw):
    n = draw(st.integers(1, 30))
    alphabet = draw(st.sampled_from(["ab", "abc", "abcdefghijklmnopqrstuvwxyz", "a"]))
    mode = draw(st.integers(0, 3))
    if mode == 0:
        word = "".join(draw(st.sampled_from(list(alphabet))) for _ in range(n))
    elif mode == 1:
        # long runs to exercise the 9-cap
        parts = []
        total = 0
        while total < n:
            c = draw(st.sampled_from(list(alphabet)))
            k = draw(st.integers(1, 25))
            parts.append(c * k)
            total += k
        word = "".join(parts)
    elif mode == 2:
        word = "a" * n
    else:
        word = "".join(sorted(draw(st.sampled_from(list(alphabet))) for _ in range(n)))
    return json.dumps(word)

