    try:
        w = json.loads(inp)
    except Exception:
        return False
    if not isinstance(w, str):
        return False
    if not (1 <= len(w) <= 2 * 10**5):
        return False
    return all('a' <= ch <= 'z' for ch in w)

def ref(inp):
