    comp = []
    i = 0
    n = len(word)
    while i < n:
        c = word[i]
        j = i
        while j < n and word[j] == c and j - i < 9:
            j += 1
        comp.append(str(j - i) + c)
        i = j
    return json.dumps("".join(comp))
