import json
from hypothesis import strategies as st

@st.composite
def gen(draw):
    mode = draw(st.integers(0, 3))
    if mode == 0:
        # single character runs of varied lengths
        word = ""
        for _ in range(draw(st.integers(1, 4))):
            c = draw(st.sampled_from("abcxyz"))
            word += c * draw(st.integers(1, 25))
    elif mode == 1:
        # all equal characters, lengths around the chunk boundary of 9
        c = draw(st.sampled_from("abz"))
        word = c * draw(st.integers(1, 30))
    elif mode == 2:
        # arbitrary small strings
        word = draw(st.text(alphabet="abc", min_size=1, max_size=30))
    else:
        # runs near multiples of 9
        word = ""
        for _ in range(draw(st.integers(1, 5))):
            c = draw(st.sampled_from("ab"))
            word += c * draw(st.sampled_from([1, 8, 9, 10, 17, 18, 19]))
    return json.dumps(word)

def validate(inp):
    try:
        w = json.loads(inp)
    except Exception:
        return False
    if not isinstance(w, str):
        return False
    if not (1 <= len(w) <= 2 * 10**5):
        return False
    return all('a' <= ch <= 'z' for ch in w)

def ref(inp):
    word = json.loads(inp)
    comp = ""
    while len(word) > 0:
        c = word[0]
        k = 0
        while k < len(word) and k < 9 and word[k] == c:
            k += 1
        comp += str(k) + c
        word = word[k:]
    return json.dumps(comp)
